<?php
// @camis:generated — do not edit; regenerated by camis

declare(strict_types=1);

namespace App\Filament\Support;

use App\Models\File;
use App\Support\StrapiFolders;
use App\Support\StrapiUpload;
use Closure;
use Filament\Actions\Action;
use Filament\Forms\Components\FileUpload;
use Filament\Forms\Components\Select;
use Filament\Forms\Components\TextInput;
use Filament\Forms\Components\Toggle;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\Gate;
use Illuminate\Support\Facades\Storage;

final class MediaPicker
{
    /** The MIME types Strapi names by their own kind; any other is a file. */
    private const KINDS = ['image', 'video', 'audio'];

    /** @param list<string>|null $allowedTypes */
    public static function make(string $field, bool $multiple, ?array $allowedTypes = null): Select
    {
        return self::picker(Select::make($field)
            ->relationship(name: $field, titleAttribute: 'name', modifyQueryUsing: fn (Builder $query): Builder => self::only($query, $allowedTypes)), $multiple, $allowedTypes);
    }

    /**
     * The same field holding the picked files' ids, for a row the form does not save itself: a
     * dynamic zone's item, which StrapiZones links once it is written.
     *
     * @param list<string>|null $allowedTypes
     */
    public static function ids(string $field, bool $multiple, ?array $allowedTypes = null): Select
    {
        return self::picker(Select::make($field)
            ->options(fn (): array => self::only(File::query(), $allowedTypes)->orderBy('name')->pluck('name', 'id')->all()), $multiple, $allowedTypes);
    }

    /** @param list<string>|null $allowedTypes */
    private static function picker(Select $select, bool $multiple, ?array $allowedTypes): Select
    {
        return $select
            ->multiple()
            ->maxItems($multiple ? null : 1)
            ->preload()
            ->searchable()
            ->rules([
                fn (): Closure => function (string $attribute, mixed $value, Closure $fail) use ($allowedTypes): void {
                    $mimes = File::query()->whereKey(array_filter((array) $value))->pluck('mime');
                    if ($mimes->contains(fn (mixed $mime): bool => ! self::allows($allowedTypes, (string) $mime))) {
                        $fail('The file type is not allowed');
                    }
                },
            ])
            ->createOptionForm(self::uploadForm($allowedTypes))
            ->createOptionUsing(fn (array $data): int => (int) self::store($data)->getKey());
    }

    /**
     * @param list<string>|null $allowedTypes
     * @return list<\Filament\Schemas\Components\Component|\Filament\Forms\Components\Field>
     */
    public static function uploadForm(?array $allowedTypes = null): array
    {
        $upload = FileUpload::make('upload')->disk('local')->directory('camis-uploads')->storeFileNamesIn('original_name')->required();
        // A browser can be told which kinds to offer, but not "anything but these", so a field that
        // takes files is checked when it is saved.
        if ($allowedTypes !== null && ! in_array('file', $allowedTypes, true)) {
            $upload->acceptedFileTypes(array_map(fn (string $kind): string => "{$kind}/*", $allowedTypes));
        }

        return [
            $upload,
            TextInput::make('alternative_text'),
            TextInput::make('caption'),
            self::folder(),
        ];
    }

    /** Where in the library a file goes: a folder, or its root. */
    public static function folder(): Select
    {
        return Select::make('folder_id')->label('Location')->placeholder('Media Library')->options(fn (): array => StrapiFolders::options());
    }

    /** Moves an admin upload from Filament's temporary disk into the media library. */
    public static function store(array $data): File
    {
        $disk = Storage::disk('local');
        $path = (string) $data['upload'];
        try {
            return StrapiUpload::storePath($disk->path($path), (string) ($data['original_name'] ?? basename($path)), [
                'alternativeText' => $data['alternative_text'] ?? null,
                'caption' => $data['caption'] ?? null,
                'folder' => $data['folder_id'] ?? null,
            ]);
        } finally {
            $disk->delete($path);
        }
    }

    /** The file the edit dialog uploads in place of the one stored: Strapi's "Replace media". */
    public static function replacement(): FileUpload
    {
        return FileUpload::make('replacement')->label('Replace media')->disk('local')->directory('camis-uploads')
            ->storeFileNamesIn('replacement_name')->imageEditor();
    }

    /**
     * Saves the edit dialog: its info and, with a replacement, what the file stores. Strapi's admin
     * sends the dialog's name with the new file, so a replaced file keeps the name shown.
     */
    public static function update(File $file, array $data): File
    {
        $file->folder_id = filled($data['folder_id'] ?? null) ? (int) $data['folder_id'] : null;
        $info = ['name' => $data['name'] ?? null, 'alternativeText' => $data['alternative_text'] ?? '', 'caption' => $data['caption'] ?? ''];

        return self::withUpload($data['replacement'] ?? null, (string) ($data['replacement_name'] ?? $file->name), fn (?UploadedFile $upload) => StrapiUpload::update($file, $info, $upload));
    }

    /**
     * Strapi's crop: the image is edited in the browser, then saved over the original ("Crop the
     * original asset") or as a new file beside it ("Duplicate & crop the asset").
     */
    public static function cropAction(): Action
    {
        return Action::make('crop')
            ->icon('heroicon-o-scissors')
            ->visible(fn (File $record): bool => in_array($record->mime, ['image/jpeg', 'image/png', 'image/webp', 'image/gif'], true))
            ->fillForm(fn (File $record): array => ['cropped' => self::workingCopy($record), 'copy' => false])
            ->schema([
                FileUpload::make('cropped')->label('Image')->disk('local')->directory('camis-uploads')->image()->imageEditor()->required(),
                Toggle::make('copy')->label('Keep the original and save the crop as a new file'),
            ])
            ->action(function (File $record, array $data): void {
                $copy = (bool) ($data['copy'] ?? false);
                Gate::authorize($copy ? 'create' : 'update', $copy ? File::class : $record);
                Storage::disk('local')->delete(self::workingPath($record));
                self::withUpload($data['cropped'] ?? null, (string) $record->name, fn (?UploadedFile $upload) => $copy && $upload !== null
                    ? StrapiUpload::store($upload, ['name' => $record->name, 'alternativeText' => $record->alternative_text, 'caption' => $record->caption, 'folder' => $record->folder_id])
                    : StrapiUpload::update($record, [], $upload));
            });
    }

    /** The stored original, copied where the crop dialog's upload field can read and edit it. */
    private static function workingCopy(File $file): string
    {
        $path = self::workingPath($file);
        $stream = StrapiUpload::disk()->readStream($file->hash.$file->ext);
        if (is_resource($stream)) {
            Storage::disk('local')->writeStream($path, $stream);
        }

        return $path;
    }

    private static function workingPath(File $file): string
    {
        return 'camis-uploads/crop-'.$file->hash.$file->ext;
    }

    /**
     * Runs a save with the dialog's upload, if any, as an uploaded file, then removes it from
     * Filament's temporary disk.
     *
     * @template T
     * @param  Closure(?UploadedFile): T  $save
     * @return T
     */
    private static function withUpload(mixed $path, string $name, Closure $save): mixed
    {
        if (! is_string($path) || $path === '') {
            return $save(null);
        }
        $disk = Storage::disk('local');
        try {
            return $save(new UploadedFile($disk->path($path), $name, null, null, true));
        } finally {
            $disk->delete($path);
        }
    }

    /** Strapi's kind of a MIME type: image, video, audio, or file. */
    public static function kind(string $mime): string
    {
        $type = strtolower(explode('/', $mime)[0]);

        return in_array($type, self::KINDS, true) ? $type : 'file';
    }

    /** @param list<string>|null $allowedTypes null for any */
    public static function allows(?array $allowedTypes, string $mime): bool
    {
        return $allowedTypes === null || in_array(self::kind($mime), $allowedTypes, true);
    }

    /** @param list<string>|null $allowedTypes */
    private static function only(Builder $query, ?array $allowedTypes): Builder
    {
        if ($allowedTypes === null) {
            return $query;
        }

        return $query->where(function (Builder $where) use ($allowedTypes): void {
            foreach (self::KINDS as $kind) {
                if (in_array($kind, $allowedTypes, true)) {
                    $where->orWhere('mime', 'like', "{$kind}/%");
                }
            }
            if (in_array('file', $allowedTypes, true)) {
                $where->orWhere(function (Builder $other): void {
                    foreach (self::KINDS as $kind) {
                        $other->where('mime', 'not like', "{$kind}/%");
                    }
                });
            }
        });
    }
}
